import os, stat, pwd, grp, hashlib, json, traceback
from pathlib import Path

root = Path('/work')
claude = root/'CLAUDE.md'
agents = root/'AGENTS.md'

def info(p: Path):
    d = {'path': str(p), 'exists': p.exists(), 'lexists': p.exists() or p.is_symlink()}
    try:
        st = os.lstat(p)
        d.update({
            'mode_octal': oct(st.st_mode & 0o7777),
            'uid': st.st_uid,
            'gid': st.st_gid,
            'is_symlink': stat.S_ISLNK(st.st_mode),
            'is_regular': stat.S_ISREG(st.st_mode),
            'is_dir': stat.S_ISDIR(st.st_mode),
        })
        if stat.S_ISLNK(st.st_mode):
            try:
                d['symlink_target'] = os.readlink(p)
            except Exception as e:
                d['symlink_target_error'] = repr(e)
    except FileNotFoundError:
        d['lstat_error'] = 'FileNotFoundError'
    except Exception as e:
        d['lstat_error'] = repr(e)
    return d

report = {'pre': {'work': info(root), 'claude': info(claude), 'agents': info(agents)}}

# Read CLAUDE.md bytes if possible
claude_bytes = None
try:
    claude_bytes = claude.read_bytes()
    report['pre']['claude_size'] = len(claude_bytes)
    report['pre']['claude_sha256'] = hashlib.sha256(claude_bytes).hexdigest()
except Exception as e:
    report['pre']['claude_read_error'] = repr(e)

# Ensure AGENTS.md canonical regular file with exact bytes
ops = []

if claude_bytes is not None:
    try:
        # If AGENTS path exists, inspect type and handle minimally
        if agents.exists() or agents.is_symlink():
            st = os.lstat(agents)
            if stat.S_ISREG(st.st_mode):
                # overwrite contents to exact bytes
                agents.write_bytes(claude_bytes)
                ops.append('overwrote existing regular /work/AGENTS.md with CLAUDE.md bytes')
            else:
                # try remove non-regular entry then create regular file
                try:
                    if stat.S_ISDIR(st.st_mode):
                        os.rmdir(agents)
                    else:
                        os.unlink(agents)
                    ops.append('removed existing non-regular /work/AGENTS.md entry')
                    agents.write_bytes(claude_bytes)
                    ops.append('created regular /work/AGENTS.md with CLAUDE.md bytes')
                except Exception as e:
                    ops.append(f'failed to replace non-regular /work/AGENTS.md: {e!r}')
        else:
            agents.write_bytes(claude_bytes)
            ops.append('created /work/AGENTS.md with CLAUDE.md bytes')
    except Exception as e:
        ops.append(f'failed to write /work/AGENTS.md: {e!r}')

# Verify AGENTS bytes
try:
    if agents.exists() and os.path.isfile(agents):
        a = agents.read_bytes()
        report['verify_agents_size'] = len(a)
        report['verify_agents_sha256'] = hashlib.sha256(a).hexdigest()
        report['verify_agents_matches_claude'] = (claude_bytes is not None and a == claude_bytes)
except Exception as e:
    report['verify_agents_error'] = repr(e)

# Attempt to remove old CLAUDE.md entry
try:
    os.unlink(claude)
    ops.append('removed /work/CLAUDE.md')
except Exception as e:
    ops.append(f'failed to remove /work/CLAUDE.md: {e!r}')

report['ops'] = ops
report['post'] = {'claude': info(claude), 'agents': info(agents)}

# If both files present regular, include mode/user details and hashes
for pkey, p in [('claude', claude), ('agents', agents)]:
    try:
        if p.exists() and os.path.isfile(p):
            b = p.read_bytes()
            report['post'][pkey+'_size'] = len(b)
            report['post'][pkey+'_sha256'] = hashlib.sha256(b).hexdigest()
    except Exception as e:
        report['post'][pkey+'_read_error'] = repr(e)

print(json.dumps(report, indent=2, sort_keys=True))
